insert into kafaa_skill_pilots (id, title_en, title_ar, hypothesis_en, hypothesis_ar, comparison_en, comparison_ar, pilot_n, comparison_n, owner_person_id, evaluator_person_id, metrics, skill_ids, start_on, end_on, status, result, recommendation, adoption, result_en, result_ar, lessons_en, lessons_ar, signoff_by, signoff_at, closed_by, closed_at, published, benchmark_ids, created_by, created_at, updated_by, updated_at, version, sort, simulated) values
('sp-vr-outage-brief', 'VR pre-job briefing for outage valve work', 'إحاطة ما قبل العمل بالواقع الافتراضي لأعمال الصمامات خلال فترات الإيقاف', 'Technicians who rehearse a valve job in VR before the outage make fewer first-time errors than technicians who get the standard classroom briefing.', 'يرتكب الفنيون الذين يتدرّبون على مهمة الصمام بالواقع الافتراضي قبل فترة الإيقاف أخطاءً أقل من المرة الأولى مقارنة بالفنيين الذين يتلقّون الإحاطة الصفية المعتادة.', 'Maintenance crews on the other unit''s outage, same valve job types, standard classroom briefing.', 'أطقم الصيانة في فترة إيقاف الوحدة الأخرى، بأنواع مهام الصمامات نفسها، مع الإحاطة الصفية المعتادة.', 24, 26, 'p-outage-manager', 'p-independent-approver', '[{"key":"first_time_right","label_en":"Jobs right first time","label_ar":"المهام المنجزة صحيحة من المرة الأولى","unit":"pct","baseline":88,"target":93,"pilot":94,"comparison":89},{"key":"rework_hours","label_en":"Rework hours","label_ar":"ساعات إعادة العمل","unit":"hours","baseline":120,"target":90,"pilot":84,"comparison":118}]'::jsonb, array['sk-fs-ai-xr','sk-mp-01-outage','sk-hu-02-brief']::text[], '2025-09-01', '2026-02-28', 'closed', 'success', 'adopted', 'adopted', 'Jobs right first time rose to 94% against 89% in the comparison crews and rework hours fell by about a third. Briefing time grew by 20 minutes per job.', 'ارتفعت نسبة المهام المنجزة صحيحة من المرة الأولى إلى 94% مقابل 89% لدى أطقم المقارنة، وانخفضت ساعات إعادة العمل بنحو الثلث. وزاد وقت الإحاطة 20 دقيقة لكل مهمة.', 'Keep the VR scene tied to the real work package; one headset per crew was enough.', 'إبقاء مشهد الواقع الافتراضي مرتبطاً بحزمة العمل الفعلية؛ وكانت نظارة واحدة لكل طاقم كافية.', 'p-independent-approver', '2026-03-12T09:00:00Z', 'p-chco', '2026-03-20T09:00:00Z', true, array['FSC']::text[], 'p-k-hr-analyst', '2025-09-01T08:00:00Z', 'p-chco', '2026-03-20T09:00:00Z', 3, 1, true),
('sp-ai-procedure-draft', 'AI-assisted first drafts of maintenance procedures', 'مسودات أولى لإجراءات الصيانة بمساعدة الذكاء الاصطناعي', 'Procedure writers who start from an approved assistant''s first draft finish a controlled revision faster without more review findings.', 'ينجز كتّاب الإجراءات الذين يبدؤون من مسودة أولى يعدّها مساعد معتمد مراجعةً مضبوطة أسرع دون زيادة في ملاحظات المراجعة.', 'Writers revising procedures of the same type and length without the assistant during the same months.', 'كتّاب يراجعون إجراءات من النوع والطول نفسيهما دون المساعد خلال الأشهر نفسها.', 12, 12, 'p-ai-governance', 'p-compliance', '[{"key":"drafting_days","label_en":"Days to a reviewable draft","label_ar":"الأيام حتى مسودة قابلة للمراجعة","unit":"days","baseline":12,"target":8,"pilot":8.5,"comparison":11.5},{"key":"review_findings","label_en":"Review findings per procedure","label_ar":"ملاحظات المراجعة لكل إجراء","unit":"count","baseline":9,"target":9,"pilot":11,"comparison":9}]'::jsonb, array['sk-fs-ai-verify','sk-fs-ai-use','sk-co-01']::text[], '2025-11-01', '2026-04-30', 'closed', 'mixed', 'further_funded', 'further_funded', 'Drafts were ready three days sooner, but reviewers raised more findings on wording copied from the assistant. Speed improved; quality did not.', 'كانت المسودات جاهزة قبل ثلاثة أيام، لكن المراجعين سجّلوا ملاحظات أكثر على صياغة منسوخة من المساعد. تحسّنت السرعة ولم تتحسّن الجودة.', 'Fund a second round with the AI verification drill before writers use the assistant.', 'تمويل جولة ثانية مع تمرين التحقق من مخرجات الذكاء الاصطناعي قبل استخدام الكتّاب للمساعد.', 'p-compliance', '2026-05-14T09:00:00Z', 'p-chco', '2026-05-25T09:00:00Z', true, array['FSC']::text[], 'p-k-hr-analyst', '2025-11-01T08:00:00Z', 'p-chco', '2026-05-25T09:00:00Z', 3, 2, true),
('sp-sim-microdrills', '20-minute simulator micro-drills between shifts', 'تمارين قصيرة على المحاكي مدتها 20 دقيقة بين الورديات', 'Short, frequent simulator drills keep emergency-procedure entry times closer to standard than the annual long session alone.', 'تحافظ تمارين المحاكي القصيرة والمتكررة على أزمنة الدخول في إجراءات الطوارئ أقرب إلى المعيار مقارنة بالجلسة السنوية الطويلة وحدها.', 'Crews on the annual long simulator session only, same quarter.', 'أطقم تكتفي بالجلسة السنوية الطويلة على المحاكي، في الربع نفسه.', 30, 28, 'p-training-mgr', 'p-independent-approver', '[{"key":"entry_within_standard","label_en":"Procedure entries within the standard time","label_ar":"الدخول في الإجراء ضمن الزمن المعياري","unit":"pct","baseline":80,"target":90,"pilot":92,"comparison":81},{"key":"drill_minutes","label_en":"Simulator minutes per person","label_ar":"دقائق المحاكي لكل شخص","unit":"count","baseline":240,"target":300,"pilot":320,"comparison":240}]'::jsonb, array['sk-co-01-eop','sk-co-02','sk-ld-02-decide']::text[], '2025-10-01', '2026-03-31', 'closed', 'success', 'expanded', 'expanded', '92% of procedure entries were within the standard time against 81% in the comparison crews; no extra simulator days were needed.', 'كانت 92% من حالات الدخول في الإجراء ضمن الزمن المعياري مقابل 81% لدى أطقم المقارنة؛ ولم تكن هناك حاجة إلى أيام محاكي إضافية.', 'Book the slots in the shift pattern, not as overtime.', 'حجز الفترات ضمن نمط الوردية، لا كعمل إضافي.', 'p-independent-approver', '2026-04-09T09:00:00Z', 'p-chco', '2026-04-20T09:00:00Z', true, array['FSC']::text[], 'p-k-hr-analyst', '2025-10-01T08:00:00Z', 'p-chco', '2026-04-20T09:00:00Z', 3, 3, true),
('sp-peer-coaching', 'Peer coaching circles for new shift technicians', 'حلقات إرشاد الأقران للفنيين الجدد في الورديات', 'New technicians in a fortnightly peer coaching circle reach their first independent task sign-off sooner.', 'يصل الفنيون الجدد المشاركون في حلقة إرشاد أقران كل أسبوعين إلى أول اعتماد مستقل لمهمة في وقت أقرب.', 'New technicians of the same intake with the usual mentor assignment only.', 'فنيون جدد من الدفعة نفسها مع تكليف المرشد المعتاد فقط.', 14, 15, 'p-training-mgr', 'p-head-sq', '[{"key":"days_to_signoff","label_en":"Days to the first independent sign-off","label_ar":"الأيام حتى أول اعتماد مستقل","unit":"days","baseline":120,"target":100,"pilot":118,"comparison":116},{"key":"circle_attendance","label_en":"Circle sessions attended","label_ar":"جلسات الحلقة التي تم حضورها","unit":"pct","baseline":0,"target":80,"pilot":46,"comparison":null}]'::jsonb, array['sk-ld-01-coach','sk-co-01-rounds']::text[], '2025-09-15', '2026-03-15', 'closed', 'failed', 'not_adopted', 'not_adopted', 'No difference in time to sign-off (118 against 116 days). Attendance fell below half once outage season began.', 'لا فرق في الزمن حتى الاعتماد (118 مقابل 116 يوماً). وانخفض الحضور إلى أقل من النصف مع بدء موسم الإيقاف.', 'Coaching that competes with shift work does not happen; build it into OJT instead.', 'الإرشاد الذي ينافس عمل الوردية لا يحدث؛ ينبغي دمجه في التدريب أثناء العمل بدلاً من ذلك.', 'p-head-sq', '2026-04-02T09:00:00Z', 'p-chco', '2026-04-14T09:00:00Z', true, array['FSC']::text[], 'p-k-hr-analyst', '2025-09-15T08:00:00Z', 'p-chco', '2026-04-14T09:00:00Z', 3, 4, true),
('sp-mobile-ojt', 'Mobile sign-off for the OJT logbook', 'الاعتماد عبر الهاتف لسجل التدريب أثناء العمل', 'Signing OJT tasks on a tablet at the job site shortens the wait for an evaluator''s sign-off.', 'يؤدي اعتماد مهام التدريب أثناء العمل على جهاز لوحي في موقع العمل إلى تقصير انتظار اعتماد المقيّم.', 'Paper logbooks signed in the training office, same job families.', 'سجلات ورقية تُعتمد في مكتب التدريب، للعائلات الوظيفية نفسها.', 40, 38, 'p-training-mgr', 'p-compliance', '[{"key":"days_waiting","label_en":"Days waiting for a sign-off","label_ar":"أيام انتظار الاعتماد","unit":"days","baseline":9,"target":3,"pilot":2.5,"comparison":8.5}]'::jsonb, array['sk-fs-dp-ework','sk-mp-01']::text[], '2025-12-01', '2026-05-31', 'closed', 'success', 'adopted', 'adopted', 'The wait for a sign-off fell from about nine days to under three; evaluators signed more tasks in the field.', 'انخفض انتظار الاعتماد من نحو تسعة أيام إلى أقل من ثلاثة؛ واعتمد المقيّمون مهام أكثر في الميدان.', 'Offline mode mattered more than any other feature in the plant.', 'كان وضع العمل دون اتصال أهم من أي ميزة أخرى داخل المحطة.', 'p-compliance', '2026-06-10T09:00:00Z', 'p-chco', '2026-06-18T09:00:00Z', true, array['FSC']::text[], 'p-k-hr-analyst', '2025-12-01T08:00:00Z', 'p-chco', '2026-06-18T09:00:00Z', 3, 5, true),
('sp-gig-weeks', 'Future-skills gig weeks', 'أسابيع المهام القصيرة لمهارات المستقبل', 'A protected week on a future-skills gig raises the share of participants with new counted evidence within three months.', 'يرفع أسبوع محمي في مهمة قصيرة لمهارات المستقبل نسبة المشاركين الذين لديهم أدلة محتسبة جديدة خلال ثلاثة أشهر.', 'Applicants to the same gigs who were not released that quarter.', 'متقدّمون للمهام نفسها لم يُفرَغوا في ذلك الربع.', 22, 25, 'p-chco', 'p-independent-approver', '[{"key":"new_evidence","label_en":"Participants with new counted evidence","label_ar":"المشاركون الذين لديهم أدلة محتسبة جديدة","unit":"pct","baseline":20,"target":50,"pilot":41,"comparison":22},{"key":"backfill_days","label_en":"Backfill days needed","label_ar":"أيام التغطية المطلوبة","unit":"days","baseline":0,"target":60,"pilot":95,"comparison":null}]'::jsonb, array['sk-fs-tr-curiosity','sk-fs-ai-automation']::text[], '2026-01-15', '2026-06-15', 'closed', 'mixed', 'further_funded', 'further_funded', 'Evidence rose (41% against 22%), short of the 50% target, and backfill cost more days than planned.', 'ارتفعت الأدلة (41% مقابل 22%)، دون هدف 50%، وكلّفت التغطية أياماً أكثر من المخطط.', 'Fund a second round with backfill agreed before release.', 'تمويل جولة ثانية مع الاتفاق على التغطية قبل الإفراغ.', 'p-independent-approver', '2026-07-02T09:00:00Z', 'p-chco', '2026-07-10T09:00:00Z', true, array['FSC']::text[], 'p-k-hr-analyst', '2026-01-15T08:00:00Z', 'p-chco', '2026-07-10T09:00:00Z', 3, 6, true),
('sp-twin-planner-drills', 'Digital-twin diagnosis drills for maintenance planners', 'تمارين التشخيص بالتوأم الرقمي لمخططي الصيانة', 'Planners who practise twin diagnosis drills spot sensor drift in work requests earlier.', 'يكتشف المخططون الذين يتدرّبون على تمارين التشخيص بالتوأم الرقمي انحراف المستشعرات في طلبات العمل في وقت أبكر.', 'Planners on the other unit without the drills.', 'مخططو الوحدة الأخرى دون التمارين.', 9, 11, 'p-ai-governance', 'p-sme-reviewer', '[{"key":"drift_flagged","label_en":"Drift cases flagged by planners","label_ar":"حالات الانحراف التي رصدها المخططون","unit":"pct","baseline":30,"target":60,"pilot":28,"comparison":31}]'::jsonb, array['sk-fs-ai-twin','sk-da-01-twins']::text[], '2026-02-01', '2026-06-30', 'closed', 'failed', 'not_adopted', 'not_adopted', 'No improvement: planners rarely see raw sensor data in their work, so the drills did not transfer. The pilot group was also below 10 people.', 'لا تحسّن: نادراً ما يرى المخططون بيانات المستشعرات الخام في عملهم، لذلك لم تنتقل التمارين إلى العمل. كما كانت مجموعة التجربة أقل من 10 أشخاص.', 'Target the drills at system engineers, who handle the data; keep this failure in the registry.', 'توجيه التمارين إلى مهندسي الأنظمة الذين يتعاملون مع البيانات؛ وإبقاء هذا الإخفاق في السجل.', 'p-sme-reviewer', '2026-07-20T09:00:00Z', 'p-chco', '2026-07-28T09:00:00Z', true, array['FSC']::text[], 'p-k-hr-analyst', '2026-02-01T08:00:00Z', 'p-chco', '2026-07-28T09:00:00Z', 3, 7, true),
('sp-lecture-capture', 'Expert lecture capture before retirement', 'تسجيل محاضرات الخبراء قبل التقاعد', 'Recorded expert lectures with a short check let successors pass the role''s knowledge check sooner.', 'تتيح محاضرات الخبراء المسجّلة مع اختبار قصير للخلفاء اجتياز اختبار المعرفة الخاص بالدور في وقت أقرب.', 'Successors in earlier handovers, before the lecture library existed.', 'الخلفاء في عمليات تسليم سابقة، قبل وجود مكتبة المحاضرات.', 18, null, 'p-chco', 'p-compliance', '[{"key":"days_to_check","label_en":"Days to pass the knowledge check","label_ar":"الأيام حتى اجتياز اختبار المعرفة","unit":"days","baseline":70,"target":50,"pilot":45,"comparison":72}]'::jsonb, array['sk-en-01','sk-fs-tr-curiosity']::text[], '2025-10-15', '2026-04-15', 'closed', 'success', 'adopted', 'adopted', 'Successors passed the knowledge check in about 45 days against 72 before the library.', 'اجتاز الخلفاء اختبار المعرفة في نحو 45 يوماً مقابل 72 يوماً قبل المكتبة.', 'Record while the expert is still in post; edit lectures into short chapters.', 'التسجيل والخبير ما زال في منصبه؛ وتقسيم المحاضرات إلى فصول قصيرة.', 'p-compliance', '2026-05-05T09:00:00Z', 'p-chco', '2026-05-12T09:00:00Z', true, array['FSC']::text[], 'p-k-hr-analyst', '2025-10-15T08:00:00Z', 'p-chco', '2026-05-12T09:00:00Z', 3, 8, true),
('sp-ai-literacy-nudges', 'Weekly AI-literacy micro-lessons', 'دروس مصغّرة أسبوعية في الإلمام بالذكاء الاصطناعي', 'Five-minute weekly micro-lessons move more staff to the Aware rung than the one-off module alone.', 'تنقل الدروس المصغّرة الأسبوعية لمدة خمس دقائق عدداً أكبر من الموظفين إلى درجة الإدراك مقارنة بالوحدة لمرة واحدة وحدها.', 'Departments that kept the one-off AI basics module only.', 'إدارات اكتفت بوحدة أساسيات الذكاء الاصطناعي لمرة واحدة.', 60, 46, 'p-ai-governance', 'p-compliance', '[{"key":"aware_share","label_en":"Staff at the Aware rung or higher","label_ar":"الموظفون في درجة الإدراك أو أعلى","unit":"pct","baseline":35,"target":55,"pilot":58,"comparison":39}]'::jsonb, array['sk-fs-ai-use','sk-da-02']::text[], '2026-05-01', '2026-09-15', 'evaluating', 'success', 'expanded', null, '58% reached the Aware rung against 39% in the comparison departments; completion held through the summer.', 'بلغ 58% درجة الإدراك مقابل 39% في إدارات المقارنة؛ واستمر الإكمال خلال الصيف.', 'Short and regular beats long and once; link each lesson to an approved tool.', 'القصير المنتظم أفضل من الطويل لمرة واحدة؛ مع ربط كل درس بأداة معتمدة.', 'p-compliance', '2026-10-05T09:00:00Z', null, null, false, array['FSC']::text[], 'p-k-hr-analyst', '2026-05-01T08:00:00Z', 'p-compliance', '2026-10-05T09:00:00Z', 2, 9, true),
('sp-adaptive-requal', 'Adaptive requalification quizzes', 'اختبارات إعادة التأهيل التكيفية', 'Adaptive quizzes that skip mastered topics cut requalification study time without lowering first-attempt pass rates.', 'تقلّص الاختبارات التكيفية التي تتخطى الموضوعات المتقنة وقت الدراسة لإعادة التأهيل دون خفض معدلات النجاح من المحاولة الأولى.', 'Licensed operators on the fixed requalification quiz in the same cycle.', 'مشغّلون مرخّصون يخضعون لاختبار إعادة التأهيل الثابت في الدورة نفسها.', 26, 27, 'p-training-mgr', 'p-independent-approver', '[{"key":"study_hours","label_en":"Study hours per person","label_ar":"ساعات الدراسة لكل شخص","unit":"hours","baseline":16,"target":11,"pilot":null,"comparison":null},{"key":"first_pass","label_en":"First-attempt pass rate","label_ar":"معدل النجاح من المحاولة الأولى","unit":"pct","baseline":92,"target":92,"pilot":null,"comparison":null}]'::jsonb, array['sk-co-01','sk-ns-02-techspec']::text[], '2026-06-01', '2026-12-15', 'running', null, null, null, '', '', '', '', null, null, null, null, false, array['FSC']::text[], 'p-k-hr-analyst', '2026-06-01T08:00:00Z', null, '2026-06-01T08:00:00Z', 1, 10, true),
('sp-rotation-buddies', 'Buddy system for future-role rotations', 'نظام الرفيق لمناوبات أدوار المستقبل', 'A buddy in the host team helps people on future-role rotations reach useful work in the first month.', 'يساعد رفيق في الفريق المضيف الأشخاص في مناوبات أدوار المستقبل على الوصول إلى عمل مفيد خلال الشهر الأول.', 'Rotations in the previous year, without a named buddy.', 'المناوبات في العام السابق، دون رفيق مسمّى.', null, null, 'p-chco', 'p-head-sq', '[{"key":"useful_week","label_en":"Week of the first useful deliverable","label_ar":"الأسبوع الذي يُسلَّم فيه أول ناتج مفيد","unit":"count","baseline":6,"target":3,"pilot":null,"comparison":null}]'::jsonb, array['sk-fs-tr-crosscultural','sk-ld-01']::text[], '2026-11-01', '2027-04-30', 'draft', null, null, null, '', '', '', '', null, null, null, null, false, array['FSC']::text[], 'p-k-hr-analyst', '2026-10-02T08:00:00Z', null, '2026-10-02T08:00:00Z', 1, 11, true)
insert into kafaa_tag_links (id, tag_id, target_table, target_id, note_en, note_ar, active, created_by, created_at, updated_by, updated_at) values
('tl:nt-nes-2031-skills:programmes:pg-fs-pack', 'nt-nes-2031-skills', 'programmes', 'pg-fs-pack', 'The future-skills course pack builds the skills the plant needs in the next decade.', 'تبني حزمة مقررات مهارات المستقبل المهارات التي تحتاجها المحطة في العقد المقبل.', true, 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('tl:nt-nes-2031-skills:programmes:pg-acad-twin', 'nt-nes-2031-skills', 'programmes', 'pg-acad-twin', 'The Digital Twin Bootcamp builds plant-data and validation skills.', 'يبني المعسكر التدريبي للتوائم الرقمية مهارات بيانات المحطة والتحقق.', true, 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('tl:nt-nes-2031-skills:critical_skills:cs-sk-fs-ai-plantdata', 'nt-nes-2031-skills', 'critical_skills', 'cs-sk-fs-ai-plantdata', 'Plant-data quality is a critical future skill on the register.', 'جودة بيانات المحطة مهارة مستقبلية حرجة في السجل.', true, 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('tl:nt-nes-2031-skills:critical_skills:cs-sk-fs-dp-rounds', 'nt-nes-2031-skills', 'critical_skills', 'cs-sk-fs-dp-rounds', 'Digital operator rounds is a critical future skill on the register.', 'الجولات التشغيلية الرقمية مهارة مستقبلية حرجة في السجل.', true, 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
